edits.newText:
def flush():
    nonlocal current
    if current:
        strokes.append(current)
        current = []

def execute(stmts):
    nonlocal heading, pen_down, current
    for stmt in stmts:
        op = stmt[0]
        if op == "fd":
            forward(stmt[1])
        elif op == "bk":
            forward(-stmt[1])
        elif op == "rt":
            heading += stmt[1]
        elif op == "lt":
            heading -= stmt[1]
        elif op == "pu":
            pen_down = False
            flush()  # break the path
        elif op == "pd":
            pen_down = True
            flush()  # start a fresh stroke on the next move

